import ast, re, pathlib, json, collections, sys

ROOT = pathlib.Path('/home/user/guidebook')
WRITE_RE = re.compile(
    r'\b(?:INSERT\s+(?:OR\s+\w+\s+)?INTO|REPLACE\s+INTO)\s+["\'`]?([A-Za-z_][A-Za-z0-9_]*)'
    r'|\bUPDATE\s+["\'`]?([A-Za-z_][A-Za-z0-9_]*)["\'`]?\s+SET'
    r'|\bDELETE\s+FROM\s+["\'`]?([A-Za-z_][A-Za-z0-9_]*)', re.I)

def sql_writes(node):
    """(table, op) pairs from every string constant under `node`."""
    out = set()
    for n in ast.walk(node):
        if isinstance(n, ast.Constant) and isinstance(n.value, str):
            for m in WRITE_RE.finditer(n.value):
                ins, upd, dele = m.group(1), m.group(2), m.group(3)
                if ins: out.add((ins, 'INSERT'))
                elif upd: out.add((upd, 'UPDATE'))
                elif dele: out.add((dele, 'DELETE'))
    return out

def called_names(node):
    out = set()
    for n in ast.walk(node):
        if isinstance(n, ast.Call):
            f = n.func
            if isinstance(f, ast.Name): out.add(f.id)
            elif isinstance(f, ast.Attribute): out.add(f.attr)
    return out

pyfiles = sorted(p for p in ROOT.glob('scripts/**/*.py'))
mod_funcs = {}   # path -> {funcname: (direct_writes, calls)}
for p in pyfiles:
    try: tree = ast.parse(p.read_text(encoding='utf-8', errors='replace'))
    except SyntaxError: continue
    funcs = {}
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)):
            funcs[n.name] = (sql_writes(n), called_names(n))
    mod_funcs[p] = funcs

def resolve(path, fname, seen=None):
    """Transitive writes of a function, following calls within the scripts tree."""
    if seen is None: seen = set()
    key = (path, fname)
    if key in seen: return set()
    seen.add(key)
    funcs = mod_funcs.get(path, {})
    if fname not in funcs:
        # look module-wide (helpers live in dbcore etc.)
        for q, fs in mod_funcs.items():
            if fname in fs:
                path, funcs = q, fs
                break
        else:
            return set()
    direct, calls = funcs[fname]
    out = set(direct)
    for c in calls:
        if c == fname: continue
        out |= resolve(path, c, seen)
    return out

print("=== writes per script file (module-level, all funcs) ===")
per_file = {}
for p, funcs in mod_funcs.items():
    w = set()
    for f in funcs: w |= funcs[f][0]
    if w: per_file[str(p.relative_to(ROOT))] = sorted(w)
for k in sorted(per_file):
    print(f'{k}: {len(per_file[k])} table-ops')

# db.py subcommand branches
src = (ROOT/'scripts/db.py').read_text()
tree = ast.parse(src)
main = next(n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name=='main')
cmd_writes = {}
def walk_if(node):
    if not isinstance(node, ast.If): return
    test = node.test
    names = []
    for c in ast.walk(test):
        if isinstance(c, ast.Compare) and isinstance(c.left, ast.Attribute) and c.left.attr=='command':
            for comp in c.comparators:
                if isinstance(comp, ast.Constant): names.append(comp.value)
                elif isinstance(comp, (ast.List, ast.Tuple)):
                    names += [e.value for e in comp.elts if isinstance(e, ast.Constant)]
    if names:
        body = ast.Module(body=node.body, type_ignores=[])
        w = sql_writes(body)
        for c in called_names(body):
            w |= resolve(ROOT/'scripts/db.py', c)
        for nm in names:
            cmd_writes.setdefault(nm, set()).update(w)
    for orelse in node.orelse:
        walk_if(orelse)
for n in main.body:
    walk_if(n)

print(f"\n=== db.py subcommands with derived writes: {len(cmd_writes)} ===")
for c in sorted(cmd_writes):
    if cmd_writes[c]:
        print(f'{c}: {sorted(cmd_writes[c])}')
