    t.cols.map(c => `<tr><td class="${c.pk ? 'pk' : ''}${c.fk ? ' fk' : ''}">${esc(c.n)}</td>
      <td style="color:var(--ink3)">${esc(c.t || '—')}</td>
      <td style="color:var(--ink3)">${[c.pk ? 'pk' : '', c.nn ? 'not null' : '',
